import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Observability","description":"","frontmatter":{},"headers":[],"relativePath":"run/observability.md","filePath":"run/observability.md"}`),a={name:`run/observability.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to “Observability”">​</a></h1><p>OpenTelemetry everywhere, shipped to OpenObserve by default (open source) or any OTLP backend. One trace per turn across processes; metrics with the GenAI semantic conventions; structured logs that carry the trace id.</p><h2 id="the-rule-adr-0003" tabindex="-1">The rule (ADR-0003) <a class="header-anchor" href="#the-rule-adr-0003" aria-label="Permalink to “The rule (ADR-0003)”">​</a></h2><p><strong>A feature is not done until it is visible on a panel.</strong> A PR that adds or changes a code path on the request side ships with:</p><ol><li>a span around the new work — <code>withSpan(&quot;area.verb&quot;, { attrs }, fn)</code>; attributes under <code>agent.*</code>;</li><li>the failure path logged with the trace id and a stable <code>error.type</code>;</li><li>a metric or a behaviour event for anything countable — <code>counter(&quot;x_total&quot;).add(1, labels)</code>, <code>histogram(&quot;x_ms&quot;, { unit: &quot;ms&quot;, boundaries: MS_BUCKETS })</code>, or <code>behaviour(&quot;kind&quot;, attrs)</code> when the runtime stepped in on the model or a product milestone happened. Labels are low-cardinality (tool, step, model, route, kind, ok) — never a session id or free text;</li><li>a panel when someone will look (observability/openobserve/dashboards.ts; <code>npm run o2:bootstrap</code> uploads them, <code>npm run o2:dashboards</code> writes the JSON for review);</li><li><code>npm run check:otel</code> still passes.</li></ol><h2 id="the-trace-tree-of-a-turn" tabindex="-1">The trace tree of a turn <a class="header-anchor" href="#the-trace-tree-of-a-turn" aria-label="Permalink to “The trace tree of a turn”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /api/chat/stream                     SERVER  (gateway/telemetry.ts; X-Trace-Id header)</span></span>
<span class="line"><span>└─ router.classify                        (two or more domains)</span></span>
<span class="line"><span>└─ invoke_agent &lt;domain&gt;                  gen_ai.conversation.id = session id</span></span>
<span class="line"><span>   ├─ runtime.step.read &lt;step&gt;            the steps engine (pre-model)</span></span>
<span class="line"><span>   ├─ chat &lt;model&gt;                        CLIENT, per model call: tokens, cost, ttft, finish</span></span>
<span class="line"><span>   │  └─ llm.attempt &lt;endpoint&gt;           one per endpoint tried (a failover reads as two)</span></span>
<span class="line"><span>   ├─ execute_tool &lt;name&gt;                 guards&#39; verdicts, carry, ms</span></span>
<span class="line"><span>   │  └─ mcp.call &lt;name&gt;                  CLIENT → the child&#39;s SERVER span mcp.tool &lt;name&gt;</span></span>
<span class="line"><span>   ├─ runtime.step.draw &lt;step&gt;            late draw / redraw</span></span>
<span class="line"><span>   └─ behaviour.* events                  create_refused, attested_dropped, step, carry…</span></span></code></pre></div><h2 id="metrics-prefix-agent-configurable" tabindex="-1">Metrics (prefix <code>agent_</code>, configurable) <a class="header-anchor" href="#metrics-prefix-agent-configurable" aria-label="Permalink to “Metrics (prefix agent_, configurable)”">​</a></h2><p><code>turns_total{domain, answered_by}</code>, <code>turn_duration_ms</code>, <code>tool_calls_total{tool, ok}</code>, <code>tool_duration_ms</code>, <code>llm_calls_total{endpoint, outcome}</code>, <code>llm_tokens_total{kind}</code>, <code>llm_cost_usd_total</code>, <code>llm_duration_ms</code>, <code>llm_ttft_ms</code>, <code>llm_failovers_total</code>, <code>llm_retries_total</code>, <code>llm_circuit_opened_total</code>, <code>llm_unavailable_total</code>, <code>llm_endpoint_open</code> (gauge), <code>behaviour_events_total{kind, step, type}</code>, <code>decisions_total{backend}</code>, <code>completions_total</code>, <code>rate_limited_total</code>, <code>usage_capped_total</code>, <code>http_requests_total</code>, <code>http_duration_ms</code>, <code>sessions_active</code>, <code>store_duration_ms</code>, <code>stt_requests_total</code>, <code>stt_seconds_total</code>, <code>process_*</code>; plus <code>gen_ai_client_token_usage</code> and <code>gen_ai_client_operation_duration</code> for backends&#39; AI views.</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to “Logs”">​</a></h2><p>JSON lines, one per event, written off the main thread (a worker batches writes; stdout is synchronous under Docker). Levels via <code>LOG_LEVEL</code>; a daily file under <code>AGENT_LOG_DIR</code> kept <code>AGENT_LOG_RETENTION_DAYS</code>; shipped to the OpenObserve logs stream when configured. Trace lines (<code>AGENT_TRACE</code> ≠ off) reconstruct a chat from the log alone: <code>turn.start</code>, <code>llm.call</code>, <code>tool.call</code>, <code>turn.done</code>, <code>turn.error</code>, <code>step</code>, <code>mcp.tool</code> (from inside the child) — grep one session id for the whole story. Secrets and phone-like numbers are masked.</p><h2 id="content-on-spans" tabindex="-1">Content on spans <a class="header-anchor" href="#content-on-spans" aria-label="Permalink to “Content on spans”">​</a></h2><p><code>AGENT_OTEL_CAPTURE_CONTENT</code>: <code>heads</code> (default — redacted 300-character heads of the user message, the reply, the system prompt and tool results), <code>full</code> (local debugging), <code>off</code>. Private user text (notes) must never sit in a label or a step event; search the telemetry for a sentinel after building a private path.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> observability/docker-compose.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # OpenObserve on :5080</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># .env</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AGENT_O2_URL</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:5080</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  AGENT_O2_USER</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">root@example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  AGENT_O2_PASSWORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">…</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> o2:bootstrap</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                                           # streams, folder, dashboards, alerts</span></span></code></pre></div><p>Gotchas learned: use protobuf exporters (OTLP/JSON rejects non-zero doubles on OpenObserve); custom attributes are stored as strings (cast in panel SQL); a field exists only after a span carried it (always emit the attributes panels filter on; prime counters at startup); the image is distroless (no compose healthcheck — poll <code>/healthz</code>).</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/OBSERVABILITY.md">docs/OBSERVABILITY.md</a> — edit it there; the site mirrors the repository.</small></p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};